module PlateReverseTapeSlotSplitTests
using ReactiveKernels, Test
import Enzyme
const RK = ReactiveKernels

# The same summed cell-loop form emitted by native lowering. Its reverse is
# generated by RK; the arithmetic below only supplies independent test values.
function split_program()
    prefix = Any[:(raw = Base.broadcastable(x)),
        :(prepared = Base.Broadcast.preprocess(nothing, raw)),
        :(total = $(GlobalRef(RK, :_plate_total_seed))(Float64, 0.0))]
    read = Expr(:call, GlobalRef(Base.Broadcast, :_broadcast_getindex), :prepared, :index)
    body = Expr(:block, :(index = Base.CartesianIndex(linear)), :(v = $read),
        :(term = $(GlobalRef(Base, :*))(s, v)),
        :(total = $(GlobalRef(RK, :_plate_total_add))(total, term)))
    loop = macroexpand(RK, Expr(:macrocall, GlobalRef(Base, Symbol("@simd")),
        LineNumberNode(0), Expr(:for, :(linear = Base.eachindex(x)), body)))
    Expr(:function, Expr(:tuple, :x, :s), Expr(:block, prefix..., loop, :total))
end

@testset "two outstanding one-pass tapes have independent storage" begin
    ast = split_program()
    rexpr, scalar, batched = RK._pr_program_reverse(ast, [:x, :s], RK, Dict{Symbol,Any}())
    @test scalar == [:s] && batched == [:x]
    @test occursin("_pr_scale_buffer!", string(rexpr))
    primal, reverse = RK.compile(ast), RK.compile(rexpr)
    rule = RK._PlateSumRule{(2,),(1,),typeof(primal),typeof(reverse)}(primal, reverse)
    z = [0.3cos(i) for i in 1:30]
    z2 = z .+ 0.2
    group = [mod1(3i, 29) for i in 1:200]
    x, x2 = view(z, group), view(z2, group)
    original = deepcopy((z, z2, group))
    @test RK._pr_rule_target(rule, (x, 0.6)) isa RK._PlateSumRuleOnePass
    slot = RK._PlateTapeSlot()
    held = zeros(length(z) + 1)
    RK._pr_return_tape!(slot, held)
    shadow = Enzyme.make_zero(slot)
    dz, dz2 = zero(z), zero(z2)
    args1 = (Enzyme.Duplicated(x, view(dz, group)), Enzyme.Active(0.6),
             Enzyme.Duplicated(slot, shadow))
    args2 = (Enzyme.Duplicated(x2, view(dz2, group)), Enzyme.Active(0.6),
             Enzyme.Duplicated(slot, shadow))
    # Operands remain unchanged between the two passes; the shared slot may
    # change. Its overwritten bit must not disable the one-pass route.
    mode = Enzyme.ReverseSplitModified(Enzyme.ReverseSplitWithPrimal,
                                      Val((false, false, false, true)))
    fwd, rev = Enzyme.autodiff_thunk(mode, Enzyme.Const{typeof(rule)},
                                   Enzyme.Active{Float64}, typeof.(args1)...)
    tape1, value1, _ = fwd(Enzyme.Const(rule), args1...)
    @test isempty(slot.tape) && any(!iszero, held)
    saved = copy(held)
    tape2, value2, _ = fwd(Enzyme.Const(rule), args2...)
    @test isempty(slot.tape) && held == saved
    cot2 = rev(Enzyme.Const(rule), args2..., 2.0, tape2)
    @test length(slot.tape) == length(held) && slot.tape !== held
    @test held == saved
    cot1 = rev(Enzyme.Const(rule), args1..., -0.5, tape1)
    @test slot.tape === held
    ds1, ds2 = only(cot1)[2], only(cot2)[2]
    @test value1 ≈ 0.6sum(x)
    @test value2 ≈ 0.6sum(x2)
    expected = zeros(length(z))
    for j in group
        expected[j] += 0.6
    end
    @test dz ≈ -0.5expected
    @test dz2 ≈ 2.0expected
    @test ds1 ≈ -0.5sum(x)
    @test ds2 ≈ 2.0sum(x2)
    @test dz[end] == dz2[end] == 0.0
    @test (z, z2, group) == original
end
end
